def is_sorted(lst):
    """Return True if the list is nonâdecreasing and no element appears more than twice."""
    # Check nonâdecreasing order
    if not all(lst[i - 1] <= lst[i] for i in range(1, len(lst))):
        return False

    # Count occurrences and ensure none exceed two
    counts = {}
    for item in lst:
        counts[item] = counts.get(item, 0) + 1
        if counts[item] > 2:
            return False

    return True
